int suche(const std::vector<int>& v, int wert) {
    int links = 0, rechts = v.size() - 1;
    while (links <= rechts) {
        int mitte = (links + rechts) / 2;
        if (v[mitte] == wert) return mitte;
        if (v[mitte] < wert) links = mitte + 1;
        else rechts = mitte - 1;
    }
    return -1;
}

